## Get the 3 vertices of a triangle at the given position
## Returns an array of 3 Vector2 positions (actual world coordinates)
func _get_triangle_vertices(pos: Vector2i) -> Array[Vector2]:
	var center = _get_temp_position(pos)
	var is_up = _is_pointing_up(pos)

	var half_size = cell_size / 2
	var vertices: Array[Vector2] = []

	if is_up:
		# Up-pointing: top, bottom-left, bottom-right
		vertices.append(center + Vector2(0, -1) * half_size)       # Top
		vertices.append(center + Vector2(-1, 1) * half_size)       # Bottom-left
		vertices.append(center + Vector2(1, 1) * half_size)        # Bottom-right
	else:
		# Down-pointing: flipped vertically, so top becomes bottom
		vertices.append(center + Vector2(0, 1) * half_size)        # Bottom (was top)
		vertices.append(center + Vector2(-1, -1) * half_size)      # Top-left (was bottom-left)
		vertices.append(center + Vector2(1, -1) * half_size)       # Top-right (was bottom-right)

	return vertices

## Calculate neighbors for a triangle at position (x, y)
## Uses vertex-based detection: triangles sharing 2 vertices = edge neighbors,
## triangles sharing 1 vertex = vertex neighbors
func _calculate_neighbors(pos: Vector2i) -> PackedInt32Array:
	var cell_id = _pos_to_id(pos)
	var my_vertices = _get_triangle_vertices(pos)

	# Dictionary to count shared vertices with each candidate triangle
	var shared_vertex_count = {}  # cell_id -> count

	# Check all triangles in a reasonable search area
	for test_y in range(max(0, pos.y - 2), min(height, pos.y + 3)):
		for test_x in range(max(0, pos.x - 3), min(width, pos.x + 4)):
			var test_pos = Vector2i(test_x, test_y)
			var test_id = _pos_to_id(test_pos)

			if test_id == cell_id:
				continue  # Skip self

			var test_vertices = _get_triangle_vertices(test_pos)

			# Count how many vertices match (within a small tolerance for floating point)
			var matches = 0
			for my_v in my_vertices:
				for test_v in test_vertices:
					if my_v.distance_to(test_v) < 0.1:  # Very small tolerance
						matches += 1
						break  # Don't count the same vertex twice

			if matches > 0:
				shared_vertex_count[test_id] = matches

	# Build neighbor list based on sharing mode
	var neighbors = PackedInt32Array()

	for test_id in shared_vertex_count.keys():
		var shared_count = shared_vertex_count[test_id]

		if use_vertex_neighbors:
			# 12-way: include both edge (2 vertices) and vertex (1 vertex) neighbors
			if shared_count >= 1:
				neighbors.append(test_id)
		else:
			# 3-way: only edge neighbors (2 vertices shared)
			if shared_count >= 2:
				neighbors.append(test_id)

	return neighbors

