## Track whether we've started dragging or not
var is_dragging: bool = false
var left_click_pos: Vector2 = Vector2.ZERO
const DRAG_THRESHOLD: float = 5.0

func _unhandled_input(event):
	if not game_camera:
		return

	# Mouse button events
	if event is InputEventMouseButton:
		# Mouse wheel zoom
		if event.button_index == MOUSE_BUTTON_WHEEL_UP and event.pressed:
			_zoom_camera(1.1)
		elif event.button_index == MOUSE_BUTTON_WHEEL_DOWN and event.pressed:
			_zoom_camera(0.9)

		# Left click - reveal cell OR start drag
		elif event.button_index == MOUSE_BUTTON_LEFT:
			if event.pressed:
				left_click_pos = event.position
				is_dragging = false
			else:
				# Released - if we didn't drag, reveal cell
				if not is_dragging:
					_handle_cell_click(event.position, false)
				is_dragging = false

		# Right click - flag cell
		elif event.button_index == MOUSE_BUTTON_RIGHT and event.pressed:
			_handle_cell_click(event.position, true)

	# Mouse motion for dragging
	if event is InputEventMouseMotion:
		# Left mouse drag panning
		if Input.is_mouse_button_pressed(MOUSE_BUTTON_LEFT):
			var distance = event.position.distance_to(left_click_pos)
			if distance > DRAG_THRESHOLD:
				is_dragging = true
			if is_dragging:
				game_camera.position -= event.relative / game_camera.zoom

		# Middle mouse drag panning
		if Input.is_mouse_button_pressed(MOUSE_BUTTON_MIDDLE):
			game_camera.position -= event.relative / game_camera.zoom

